function pickInstanceType(types, needCpu, needMem) {
  const fits = types.filter((t) => t.vcpu >= needCpu);
  if (!fits.length) return null;
  fits.sort((a, b) => a.hourly - b.hourly);
  return fits[0].name;
}

coding.referenceSolution:
function pickInstanceType(types, needCpu, needMem) {
  const fits = types.filter((t) => t.vcpu >= needCpu && t.memGiB >= needMem);
  if (!fits.length) return null;
  fits.sort((a, b) => a.hourly - b.hourly);
  return fits[0].name;
}

