coding.referenceSolution:
def risky_rules(rules, allowed_public):
    out = []
    for r in rules:
        if r["cidr"] not in ("0.0.0.0/0", "::/0"):
            continue
        allowed_in_range = sum(1 for p in set(allowed_public) if r["from"] <= p <= r["to"])
        if allowed_in_range < r["to"] - r["from"] + 1:
            out.append(r["id"])
    return out

