function planBatches(ids, minHealthyPct) {
  const size = Math.max(1, Math.ceil((ids.length * (100 - minHealthyPct)) / 100));
  const out = [];
  for (let i = 0; i < ids.length; i += size) out.push(ids.slice(i, i + size));
  return out;
}

